// Vocabulario temático (B2 y C1): una lección extra («bonus», id `wortschatz`) por unidad elegida.
// Suma campo léxico (salud, derecho, economía, medio ambiente, historia, política, finanzas) a unidades
// que son sobre todo de estructura. Cada lección trae unas 12 palabras con ejemplo, ejercicios y un
// diálogo corto en registro hablado (partículas, ironía, frases cortadas), no un interrogatorio.

import type { Lesson, ListenQuestion, Vocab, HandExercise } from "../curriculum.ts";

type L = ["f" | "m", string, string, string];
type Cloze = Extract<HandExercise, { kind: "cloze" }>;

const w = (de: string, es: string, emoji: string, exDe: string, exEs: string, note?: string): Vocab => ({ de, es, emoji, example: { de: exDe, es: exEs }, ...(note ? { note } : {}) });
const cz = (sentence: string, es: string, options: string[], answer: string, explanation: string): Cloze => ({ kind: "cloze", sentence, es, options, answer, explanation, category: "vocabulario" });

const thema = (
  title: string,
  icon: string,
  goal: string,
  intro: string[],
  summary: string[],
  vocab: Vocab[],
  exercises: HandExercise[],
  dTitle: string,
  setting: string,
  lines: L[],
  questions: ListenQuestion[],
): Lesson => ({
  id: "wortschatz",
  title: `Vocabulario: ${title}`,
  goal,
  icon,
  bonus: true,
  intro,
  summary,
  vocab,
  exercises,
  dialogue: { title: dTitle, setting, lines: lines.map(([who, name, de, es]) => ({ who, name, de, es })), questions },
});

